 const nav=[['dashboard',LayoutDashboard,t('Privire de ansamblu','Overview')],['reports',Receipt,t('Deconturi','Expense reports')],...(role('Manager')?[['approvals',CheckCheck,t('Aprobări','Approvals')]]:[]),...(role('Finance')?[['finance',Building2,'Finance'],['cards',WalletCards,t('Carduri și tranzacții','Cards & transactions')]]:[]),...(role('Finance')||role('Admin')?[['settings',Settings,t('Nomenclatoare','Master data')]]:[]),...(role('Admin')?[['users',Users,t('Utilizatori și acces','Users & access')],['delegations',Clock,t('Delegări','Delegations')],['jobs',Clock,t('Operațiuni de fundal','Background jobs')]]:[]),...(role('Finance')||role('Admin')||role('Auditor')?[['audit',ShieldCheck,t('Jurnal de audit','Audit log')]]:[])];
